var root = source.getKey();
var options = JSON.stringify({headers:{'User-Agent':'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36'}});
var doc = org.jsoup.Jsoup.parse(java.ajax(root+','+options), root);
var rows = [], seen = {};
doc.select("#nav a[href^='/lists/'],#nav a[href^='/all/'],#nav a[href^='/other/rank_hits/'],#nav a[href='/original.html']").forEach(function(a) {
  var url = String(a.absUrl('href')).split('?')[0];
  var title = String(a.text()).trim();
  if (title && !seen[url]) {
    seen[url] = true;
    rows.push({title:title,url:url+(url.indexOf('/other/rank_hits/') >= 0 ? '' : '?page={{page}}')+','+options});
  }
});
if (!rows.length) throw new Error('Site navigation is empty');
JSON.stringify(rows);

