function setDefaultSettings() {
    const {java, cache} = this
    let settings = {}
    settings.SEARCH_AUTHOR = false      // 搜索：默认不搜索作者名称
    settings.CONVERT_CHINESE = true     // 搜索：搜索时进行繁简转换

    settings.SHOW_CAPTIONS = true       // 正文：章首显示描述
    settings.SHOW_PICTURES = true       // 正文：正文显示图片，但会增加少许请求

    settings.COMBINE_NOVELS = true      // 全局：整合系列
    settings.IPDirect = false           // 全局：直连模式
    settings.FAST  = false              // 全局：快速模式

    Object.assign(settings, this.getDefaultDiscoverSettings())
    settings.DISCOVERY_DEFAULTS_VERSION = 1

    this.putInCacheObject("pixivSettings", settings)
    return settings
}
function checkSettings(settings) {
    const {java, cache} = this
    if (!settings) settings = this.getFromCacheObject("pixivSettings")
    if (!settings) settings = this.setDefaultSettings()
    if (settings.FAST) {
        settings.CONVERT_CHINESE = false      // 搜索：繁简通搜

        settings.SHOW_PICTURES = false        // 正文：显示图片
    }

    // 新设置初始化
    if (settings.SHOW_PICTURES === undefined) settings.SHOW_PICTURES = true
    if (settings.COMBINE_NOVELS === undefined) settings.COMBINE_NOVELS = true
    let discoveryDefaults = this.getDefaultDiscoverSettings()
    if (!settings.DISCOVERY_DEFAULTS_VERSION) {
        // 只迁移旧版默认组合；自定义分类和已关闭的首页栏目保持不变。
        let legacyDefaults = {
            SHOW_ADULT: true, SHOW_GENERAL: true,
            SHOW_NEW_ADULT: true, SHOW_NEW_GENERAL: false,
            SHOW_RANK_ADULT: true, SHOW_RANK_GENERAL: false,
            SHOW_GENRE_ADULT: false, SHOW_GENRE_GENERAL: false,
        }
        let legacyKeys = Object.keys(legacyDefaults)
        let defaultHomepage = Object.keys(discoveryDefaults).filter(key => discoveryDefaults[key] === true)
            .every(key => settings[key] === undefined || settings[key] === true)
        if (defaultHomepage && legacyKeys.every(key => settings[key] === legacyDefaults[key])) {
            legacyKeys.forEach(key => { settings[key] = discoveryDefaults[key] })
        }
        settings.DISCOVERY_DEFAULTS_VERSION = 1
    }
    Object.keys(discoveryDefaults).forEach(key => {
        if (settings[key] === undefined) settings[key] = discoveryDefaults[key]
    })

    this.putInCacheObject("pixivSettings", settings)
    return settings
}

